#!/usr/bin/env python3\n\"\"\"\nGemma-3 VLM Embedding Service\nMultimodal embeddings: Text + Vision + Layout + Seal Confidence\nOutput: 1024-dimensional fused embeddings\n\"\"\"\n\nimport asyncio\nimport logging\nimport time\nfrom typing import List, Dict, Any, Optional, Tuple\nfrom dataclasses import dataclass\nimport numpy as np\nimport torch\nfrom transformers import AutoModelForVision2Seq, AutoProcessor\nfrom PIL import Image\nimport io\nimport base64\nfrom fastapi import FastAPI, HTTPException\nfrom pydantic import BaseModel\nimport uvicorn\n\nlogging.basicConfig(level=logging.INFO)\nlogger = logging.getLogger(__name__)\n\n@dataclass\nclass EmbeddingRequest:\n    \"\"\"Multimodal embedding request\"\"\"\n    text: str\n    image: Optional[bytes] = None\n    file_path: str = \"\"\n    language: str = \"english\"\n    chunk_id: str = \"\"\n    metadata: Dict[str, Any] = None\n    seal_confidence: float = 0.0  # From YOLO detector\n    layout_boxes: List[Dict] = None  # From DocLing\n\n@dataclass\nclass EmbeddingResponse:\n    \"\"\"Embedding response with 1024d vector\"\"\"\n    chunk_id: str\n    embedding: List[float]  # Always 1024 dimensions\n    modality: str  # \"text\", \"image\", \"multimodal\"\n    processing_time_ms: float\n    token_count: int\n    model_name: str\n    seal_confidence: float\n    layout_boxes: List[Dict]\n\nclass GemmaVLMEmbeddingService:\n    \"\"\"Gemma-3 VLM service for 1024d multimodal embeddings\"\"\"\n    \n    def __init__(\n        self,\n        model_name: str = \"google/gemma-3-2b-it-v\",\n        device: str = \"auto\",\n        batch_size: int = 4,\n        max_length: int = 512,\n        cache_dir: Optional[str] = None\n    ):\n        self.model_name = model_name\n        self.batch_size = batch_size\n        self.max_length = max_length\n        self.cache_dir = cache_dir or \"./models/cache\"\n        \n        # Device setup\n        if device == \"auto\":\n            self.device = \"cuda\" if torch.cuda.is_available() else \"cpu\"\n        else:\n            self.device = device\n        \n        logger.info(f\"🚀 Initializing Gemma-3 VLM on {self.device}\")\n        \n        # Model and processor (loaded lazily)\n        self.processor: Optional[AutoProcessor] = None\n        self.model: Optional[AutoModelForVision2Seq] = None\n        self.is_loaded = False\n        \n        # Performance tracking\n        self.total_requests = 0\n        self.total_processing_time = 0.0\n    \n    async def load_model(self) -> None:\n        \"\"\"Load VLM model and processor\"\"\"\n        if self.is_loaded:\n            return\n        \n        logger.info(f\"📥 Loading {self.model_name}...\")\n        start_time = time.time()\n        \n        try:\n            # Load processor (handles both text and images)\n            self.processor = AutoProcessor.from_pretrained(\n                self.model_name,\n                cache_dir=self.cache_dir,\n                trust_remote_code=True\n            )\n            \n            # Load VLM model\n            self.model = AutoModelForVision2Seq.from_pretrained(\n                self.model_name,\n                cache_dir=self.cache_dir,\n                torch_dtype=torch.float16 if self.device == \"cuda\" else torch.float32,\n                device_map=self.device,\n                trust_remote_code=True\n            )\n            \n            self.model.eval()\n            \n            # Enable optimizations\n            if self.device == \"cuda\":\n                try:\n                    self.model = torch.compile(self.model, mode=\"reduce-overhead\")\n                except:\n                    logger.warning(\"⚠️ torch.compile not available, skipping\")\n            \n            load_time = time.time() - start_time\n            logger.info(f\"✅ Model loaded in {load_time:.2f}s\")\n            \n            # Verify embedding dimension\n            test_embedding = await self._generate_single_embedding(\"test\")\n            if len(test_embedding) != 1024:\n                raise ValueError(f\"Expected 1024d embeddings, got {len(test_embedding)}d\")\n            \n            logger.info(f\"🎯 Verified 1024-dimensional embeddings\")\n            self.is_loaded = True\n            \n        except Exception as e:\n            logger.error(f\"❌ Failed to load model: {e}\")\n            raise\n    \n    async def generate_embeddings(\n        self,\n        requests: List[EmbeddingRequest]\n    ) -> List[EmbeddingResponse]:\n        \"\"\"Generate multimodal embeddings for multiple requests\"\"\"\n        if not self.is_loaded:\n            await self.load_model()\n        \n        if not requests:\n            return []\n        \n        logger.info(f\"🔄 Processing {len(requests)} embedding requests\")\n        start_time = time.time()\n        \n        responses = []\n        \n        # Process in batches\n        for i in range(0, len(requests), self.batch_size):\n            batch = requests[i:i + self.batch_size]\n            batch_responses = await self._process_batch(batch)\n            responses.extend(batch_responses)\n        \n        total_time = time.time() - start_time\n        self.total_requests += len(requests)\n        self.total_processing_time += total_time\n        \n        avg_time = (total_time / len(requests)) * 1000  # ms per request\n        logger.info(f\"✅ Generated {len(responses)} embeddings in {total_time:.2f}s ({avg_time:.1f}ms/req)\")\n        \n        return responses\n    \n    async def _process_batch(self, batch: List[EmbeddingRequest]) -> List[EmbeddingResponse]:\n        \"\"\"Process a batch of embedding requests\"\"\"\n        batch_start = time.time()\n        \n        responses = []\n        \n        for req in batch:\n            try:\n                # Determine modality\n                if req.image:\n                    modality = \"multimodal\"\n                    embedding = await self._generate_multimodal_embedding(\n                        req.text,\n                        req.image,\n                        req.seal_confidence,\n                        req.layout_boxes or []\n                    )\n                else:\n                    modality = \"text\"\n                    embedding = await self._generate_single_embedding(req.text)\n                \n                # Verify dimension\n                assert len(embedding) == 1024, f\"Expected 1024d, got {len(embedding)}d\"\n                \n                batch_time = time.time() - batch_start\n                \n                response = EmbeddingResponse(\n                    chunk_id=req.chunk_id,\n                    embedding=embedding,\n                    modality=modality,\n                    processing_time_ms=(batch_time / len(batch)) * 1000,\n                    token_count=len(self.processor.tokenize(req.text)),\n                    model_name=self.model_name,\n                    seal_confidence=req.seal_confidence,\n                    layout_boxes=req.layout_boxes or []\n                )\n                responses.append(response)\n                \n            except Exception as e:\n                logger.error(f\"❌ Error processing chunk {req.chunk_id}: {e}\")\n                raise\n        \n        return responses\n    \n    async def _generate_single_embedding(self, text: str) -> List[float]:\n        \"\"\"Generate text-only embedding\"\"\"\n        inputs = self.processor(\n            text=text,\n            return_tensors=\"pt\",\n            padding=True,\n            truncation=True,\n            max_length=self.max_length\n        ).to(self.device)\n        \n        with torch.no_grad():\n            outputs = self.model(**inputs)\n            \n            # Extract embeddings from last hidden state\n            embeddings = outputs.last_hidden_state\n            \n            # Mean pooling\n            attention_mask = inputs.get('attention_mask')\n            if attention_mask is not None:\n                mask_expanded = attention_mask.unsqueeze(-1).expand(embeddings.size()).float()\n                embeddings = torch.sum(embeddings * mask_expanded, 1) / torch.clamp(mask_expanded.sum(1), min=1e-9)\n            else:\n                embeddings = embeddings.mean(dim=1)\n            \n            # L2 normalization\n            embeddings = torch.nn.functional.normalize(embeddings, p=2, dim=1)\n            \n            # Ensure 1024d (pad if necessary)\n            if embeddings.shape[1] < 1024:\n                padding = torch.zeros(embeddings.shape[0], 1024 - embeddings.shape[1]).to(self.device)\n                embeddings = torch.cat([embeddings, padding], dim=1)\n            elif embeddings.shape[1] > 1024:\n                embeddings = embeddings[:, :1024]\n            \n            return embeddings.cpu().numpy()[0].tolist()\n    \n    async def _generate_multimodal_embedding(\n        self,\n        text: str,\n        image_bytes: bytes,\n        seal_confidence: float,\n        layout_boxes: List[Dict]\n    ) -> List[float]:\n        \"\"\"Generate multimodal embedding (text + vision + layout + seal)\"\"\"\n        try:\n            # Decode image\n            image = Image.open(io.BytesIO(image_bytes)).convert(\"RGB\")\n            \n            # Process multimodal input\n            inputs = self.processor(\n                text=text,\n                images=image,\n                return_tensors=\"pt\",\n                padding=True,\n                truncation=True,\n                max_length=self.max_length\n            ).to(self.device)\n            \n            with torch.no_grad():\n                outputs = self.model(**inputs)\n                \n                # Extract embeddings\n                embeddings = outputs.last_hidden_state\n                \n                # Mean pooling\n                attention_mask = inputs.get('attention_mask')\n                if attention_mask is not None:\n                    mask_expanded = attention_mask.unsqueeze(-1).expand(embeddings.size()).float()\n                    embeddings = torch.sum(embeddings * mask_expanded, 1) / torch.clamp(mask_expanded.sum(1), min=1e-9)\n                else:\n                    embeddings = embeddings.mean(dim=1)\n                \n                # Fuse with layout and seal information\n                embedding_np = embeddings.cpu().numpy()[0]\n                \n                # Add layout signal (box coordinates normalized)\n                if layout_boxes:\n                    layout_signal = np.zeros(64)  # 64d layout signal\n                    for i, box in enumerate(layout_boxes[:16]):  # Max 16 boxes\n                        idx = i * 4\n                        if idx + 4 <= 64:\n                            layout_signal[idx:idx+4] = [\n                                box.get('x', 0) / 1000,\n                                box.get('y', 0) / 1000,\n                                box.get('width', 0) / 1000,\n                                box.get('height', 0) / 1000\n                            ]\n                    embedding_np = np.concatenate([embedding_np, layout_signal])\n                \n                # Add seal confidence signal (256d)\n                seal_signal = np.ones(256) * seal_confidence\n                embedding_np = np.concatenate([embedding_np, seal_signal])\n                \n                # Ensure 1024d total\n                if len(embedding_np) < 1024:\n                    padding = np.zeros(1024 - len(embedding_np))\n                    embedding_np = np.concatenate([embedding_np, padding])\n                elif len(embedding_np) > 1024:\n                    embedding_np = embedding_np[:1024]\n                \n                # L2 normalization\n                embedding_np = embedding_np / np.linalg.norm(embedding_np)\n                \n                return embedding_np.tolist()\n                \n        except Exception as e:\n            logger.error(f\"❌ Multimodal embedding failed: {e}\")\n            raise\n    \n    def get_stats(self) -> Dict[str, Any]:\n        \"\"\"Get service statistics\"\"\"\n        avg_time = (self.total_processing_time / max(self.total_requests, 1)) * 1000\n        \n        return {\n            \"model_name\": self.model_name,\n            \"device\": self.device,\n            \"is_loaded\": self.is_loaded,\n            \"embedding_dimension\": 1024,\n            \"batch_size\": self.batch_size,\n            \"max_length\": self.max_length,\n            \"total_requests\": self.total_requests,\n            \"total_processing_time\": self.total_processing_time,\n            \"avg_processing_time_ms\": avg_time,\n            \"gpu_available\": torch.cuda.is_available(),\n            \"gpu_memory_allocated\": torch.cuda.memory_allocated() if torch.cuda.is_available() else 0,\n            \"gpu_memory_reserved\": torch.cuda.memory_reserved() if torch.cuda.is_available() else 0\n        }\n    \n    async def health_check(self) -> Dict[str, Any]:\n        \"\"\"Health check endpoint\"\"\"\n        try:\n            if not self.is_loaded:\n                await self.load_model()\n            \n            # Test embedding generation\n            test_start = time.time()\n            test_embedding = await self._generate_single_embedding(\"health check test\")\n            test_time = (time.time() - test_start) * 1000\n            \n            return {\n                \"status\": \"healthy\",\n                \"model_loaded\": True,\n                \"embedding_dimension\": len(test_embedding),\n                \"test_inference_time_ms\": test_time,\n                \"device\": self.device,\n                \"timestamp\": time.time()\n            }\n            \n        except Exception as e:\n            logger.error(f\"❌ Health check failed: {e}\")\n            return {\n                \"status\": \"unhealthy\",\n                \"error\": str(e),\n                \"model_loaded\": self.is_loaded,\n                \"device\": self.device,\n                \"timestamp\": time.time()\n            }\n    \n    async def shutdown(self) -> None:\n        \"\"\"Cleanup resources\"\"\"\n        logger.info(\"🛑 Shutting down Gemma-3 VLM service\")\n        \n        if self.model is not None:\n            del self.model\n        \n        if self.processor is not None:\n            del self.processor\n        \n        if torch.cuda.is_available():\n            torch.cuda.empty_cache()\n        \n        self.is_loaded = False\n        logger.info(\"✅ Gemma-3 VLM service shutdown complete\")\n\n\n# FastAPI Integration\napp = FastAPI(title=\"Gemma-3 VLM Embedding Service\", version=\"1.0.0\")\nservice = GemmaVLMEmbeddingService()\n\nclass EmbedRequest(BaseModel):\n    texts: List[str]\n    images: List[Optional[str]] = []  # Base64 encoded\n    file_paths: List[str] = []\n    languages: List[str] = []\n    chunk_ids: List[str] = []\n    seal_confidences: List[float] = []\n    layout_boxes: List[List[Dict]] = []\n    metadata: List[Dict[str, Any]] = []\n\nclass EmbedResponse(BaseModel):\n    embeddings: List[List[float]]\n    modalities: List[str]\n    processing_time_ms: float\n    model_name: str\n    embedding_dimension: int\n\n@app.on_event(\"startup\")\nasync def startup():\n    await service.load_model()\n\n@app.on_event(\"shutdown\")\nasync def shutdown():\n    await service.shutdown()\n\n@app.post(\"/embed\", response_model=EmbedResponse)\nasync def embed_texts(request: EmbedRequest):\n    try:\n        # Convert to EmbeddingRequest objects\n        requests = []\n        for i, text in enumerate(request.texts):\n            image_bytes = None\n            if i < len(request.images) and request.images[i]:\n                image_bytes = base64.b64decode(request.images[i])\n            \n            req = EmbeddingRequest(\n                text=text,\n                image=image_bytes,\n                file_path=request.file_paths[i] if i < len(request.file_paths) else \"\",\n                language=request.languages[i] if i < len(request.languages) else \"english\",\n                chunk_id=request.chunk_ids[i] if i < len(request.chunk_ids) else f\"chunk_{i}\",\n                seal_confidence=request.seal_confidences[i] if i < len(request.seal_confidences) else 0.0,\n                layout_boxes=request.layout_boxes[i] if i < len(request.layout_boxes) else [],\n                metadata=request.metadata[i] if i < len(request.metadata) else {}\n            )\n            requests.append(req)\n        \n        # Generate embeddings\n        start_time = time.time()\n        responses = await service.generate_embeddings(requests)\n        total_time = (time.time() - start_time) * 1000\n        \n        return EmbedResponse(\n            embeddings=[resp.embedding for resp in responses],\n            modalities=[resp.modality for resp in responses],\n            processing_time_ms=total_time,\n            model_name=service.model_name,\n            embedding_dimension=1024\n        )\n        \n    except Exception as e:\n        logger.error(f\"❌ Embedding error: {e}\")\n        raise HTTPException(status_code=500, detail=str(e))\n\n@app.get(\"/health\")\nasync def health():\n    return await service.health_check()\n\n@app.get(\"/stats\")\nasync def stats():\n    return service.get_stats()\n\nif __name__ == \"__main__\":\n    uvicorn.run(app, host=\"0.0.0.0\", port=8001, log_level=\"info\")\n"